using System;public class Solution{int m,n;int F(int[][]a,int r,int c,int[][]dp){if(dp[r][c]!=0)return dp[r][c];int[][]d={new[]{1,0},new[]{-1,0},new[]{0,1},new[]{0,-1}};dp[r][c]=1;foreach(var z in d){int x=r+z[0],y=c+z[1];if(x>=0&&y>=0&&x<m&&y<n&&a[x][y]>a[r][c])dp[r][c]=Math.Max(dp[r][c],1+F(a,x,y,dp));}return dp[r][c];}public int LongestIncreasingPath(int[][]a){if(a.Length==0)return 0;m=a.Length;n=a[0].Length;int[][]dp=new int[m][];for(int i=0;i<m;i++)dp[i]=new int[n];int b=0;for(int i=0;i<m;i++)for(int j=0;j<n;j++)b=Math.Max(b,F(a,i,j,dp));return b;}}
